proposed_api_examples:
# async example:
async for ev in client.chat.stream_messages(model="rwd-3b", prompt=msg):
    if ev.type == "delta":
        print(ev.text, end="")
    elif ev.type == "function_call":
        handle_call(ev)

# sync example:
for ev in client.chat.stream_messages_sync(model="rwd-3b", prompt=msg):
    if ev.type == "delta":
        buffer.append(ev.text)
    elif ev.type == "done":
        break

# resume example (server must support resume_token):
try:
    async for ev in client.chat.stream_messages(...):
        process(ev)
except StreamInterruptedError as e:
    if e.resume_token:
        async for ev in client.chat.stream_messages(resume_token=e.resume_token):
            process(ev)
